def kind_of(item_id: str) -> str | None:
    """Return the item kind, or None for an unknown id."""
    if item_id in WEAPONS:
        return KIND_WEAPON
    if item_id in AMMO:
        return KIND_AMMO
    if item_id in ATTACHMENTS:
        return KIND_ATTACHMENT
    if item_id in ARMORS:
        return KIND_ARMOR
    if item_id in HELMETS:
        return KIND_HELMET
    if item_id in BACKPACKS:
        return KIND_BACKPACK
    if item_id in HEALS:
        return KIND_HEAL
    if item_id in THROWABLES:
        return KIND_THROWABLE
    return None


def is_stackable(item_id: str) -> bool:
    """Stackable items live in the backpack dict and use ITEM_SPACE."""
    return item_id in ITEM_SPACE


def item_space(item_id: str) -> float:
    return ITEM_SPACE.get(item_id, 0.0)


def is_compatible(weapon_id: str, attachment_id: str) -> bool:
    weapon = WEAPONS.get(weapon_id)
    attachment = ATTACHMENTS.get(attachment_id)
    if weapon is None or attachment is None:
        return False
    return attachment.slot in weapon.attachment_slots and weapon_id in attachment.compatible


def mag_capacity(slot: WeaponSlot) -> int:
    """Magazine size including an extended magazine."""
    weapon = WEAPONS.get(slot.weapon_id)
    if weapon is None:
        return 0
    bonus = sum(ATTACHMENTS[a].mag_bonus for a in slot.attachments.values() if a in ATTACHMENTS)
    return weapon.mag_size + bonus


def cone_degrees(slot: WeaponSlot) -> float:
    weapon = WEAPONS.get(slot.weapon_id)
    if weapon is None:
        return 0.0
    cone = weapon.aim_cone_degrees
    for attachment_id in slot.attachments.values():
        spec = ATTACHMENTS.get(attachment_id)
        if spec is not None:
            cone *= spec.cone_multiplier
    return cone


def accuracy_bonus(slot: WeaponSlot) -> float:
    return sum(ATTACHMENTS[a].accuracy_bonus for a in slot.attachments.values() if a in ATTACHMENTS)
